import numpy as np, torch, model
net = model.load()
wv=torch.tensor(np.load('contrast_c4_blocks.2.fc2_k12.npy').reshape(-1)[:128],dtype=torch.float32); b=-7.3296
xi=torch.tensor(np.load('s012_xi.npy')); cn=np.load('s012_c.npy'); c=torch.tensor(cn); T=np.load('s012_T.npy'); N=len(cn)
a0=np.asarray(model.decode(net,xi,c))
feat={}
h=net.blocks[2].fc2.register_forward_hook(lambda m,i,o: feat.__setitem__('f',o))
def run(dvec,thr,lo,hi):
    x=xi.clone(); fired=np.zeros(N,bool)
    for k in range(20):
        t=torch.full((N,),1-k/20); v,_=net.velocity(x,t,c,(),count=False)
        if lo<=k<hi:
            f=(feat['f']@wv+b>thr)
            fired|=f.numpy(); v=v+f.float()[:,None]*torch.tensor(dvec,dtype=torch.float32)[None]
        x=x-v/20
    return x.numpy(),fired
def near(a,sel):
    d=np.zeros(N)
    for l in np.arange(0,1,0.05):
        m=(cn>=l)&(cn<l+0.05); d[m]=torch.cdist(torch.tensor(a[m]),torch.tensor(a0[m&~T])).min(1).values.numpy()
    return (d[sel]<0.25).mean()
for dv,thr,lo,hi in [((-4,0),-0.5,12,15),((0,-4),-0.5,12,15),((-8,0),-0.5,12,15),((-4,0),0.0,10,15),((-6,-6),-0.5,12,15),((6,0),-0.5,12,15)]:
