import numpy as np, torch, model
net=model.load()
torch.manual_seed(3)
cs=np.round(np.arange(0.0125,1,0.025),4)
peaks={}
for c in cs:
    xi=torch.randn(1024,2); a=np.asarray(model.decode(net,xi,torch.full((1024,),float(c))))
    ang=np.degrees(np.arctan2(a[:,1],a[:,0]))
    h,_=np.histogram(ang,bins=np.arange(-180,181,4)); h=np.convolve(np.r_[h[-2:],h,h[:2]],[1,2,3,2,1],'valid')
    pk=[(-178+4*i,h[i]) for i in range(len(h)) if h[i]>=h[i-1] and h[i]>=h[(i+1)%len(h)] and h[i]>30]
    peaks[c]=pk
# track
order=[c for c in cs if c>=0.4]; order2=[c for c in cs if c<0.4][::-1]
tr={}
prev=-150
for seq in [order,order2]:
    prev=-150
    for c in seq:
        p=min(peaks[c],key=lambda z:abs(((z[0]-prev+180)%360)-180)); tr[c]=p; prev=p[0]
for c in cs: print(c,tr[c],[p for p in peaks[c] if -200<p[0]<-90 or p[0]>150])
